BUNDLE["CardDefs"] = [====[
local CardDefs = {}

CardDefs.Colors = { "Red", "Yellow", "Green", "Blue" }

-- Color3 exists inside Roblox; fall back to raw RGB tables outside it (tests).
local function rgb(r, g, b)
	if Color3 then
		return Color3.fromRGB(r, g, b)
	end
	return { r, g, b }
end

CardDefs.ColorHex = {
	Red = rgb(214, 41, 49),
	Yellow = rgb(255, 200, 0),
	Green = rgb(0, 128, 64),
	Blue = rgb(36, 90, 199),
	Black = rgb(24, 24, 28),
}

CardDefs.Kinds = { "number", "skip", "reverse", "drawtwo", "wild", "wilddrawfour" }

CardDefs.Glyphs = {
	skip = "SKIP",
	reverse = "REV",
	drawtwo = "+2",
	wild = "WILD",
	wilddrawfour = "+4",
}

local nextId = 0
local function newCard(kind, color, value)
	nextId = nextId + 1
	if kind == "number" then
		return { id = nextId, kind = kind, color = color, value = value }
	end
	return { id = nextId, kind = kind, color = color, value = value }
end

-- Official 108-card deck: per suit 1x of 0..9, 2x each 1..9/action; 4 Wild, 4 Wild Draw Four
function CardDefs.buildDeck()
	local deck = {}
	for _, color in ipairs(CardDefs.Colors) do
		for v = 0, 9 do
			local copies = 1
			if v > 0 then
				copies = 2
			end
			for _ = 1, copies do
				table.insert(deck, newCard("number", color, v))
			end
		end
		for _ = 1, 2 do
			table.insert(deck, newCard("skip", color, 0))
			table.insert(deck, newCard("reverse", color, 0))
			table.insert(deck, newCard("drawtwo", color, 0))
		end
	end
	for _ = 1, 4 do
		table.insert(deck, newCard("wild", nil, 0))
		table.insert(deck, newCard("wilddrawfour", nil, 0))
	end
	return deck
end

-- Is the discard top face-up vs face-down irrelevant here; we always keep cards with color nil meaning wild.
-- Wild cards never carry a color, matching official deck.

function CardDefs.cardName(card)
	if not card then
		return "?"
	end
	if card.kind == "number" then
		return card.color .. " " .. card.value
	end
	local glyph = CardDefs.Glyphs[card.kind] or card.kind
	if card.color then
		return card.color .. " " .. glyph
	end
	return glyph
end

function CardDefs.points(card)
	if not card then
		return 0
	end
	if card.kind == "number" then
		return card.value
	end
	if card.kind == "wild" or card.kind == "wilddrawfour" then
		return 50
	end
	return 20
end

return CardDefs
