BUNDLE["Rules"] = [====[
local CardDefs = require(script.Parent.CardDefs)

local Rules = {}

-- A card is playable if it matches color, number, or symbol of the top card.
-- Wild cards are always playable.
function Rules.canPlay(card, topCard, currentColor)
	card = card or {}
	topCard = topCard or {}
	if card.kind == "wild" or card.kind == "wilddrawfour" then
		return true
	end
	if topCard.kind == "wild" or topCard.kind == "wilddrawfour" then
		-- After a wild, only color matters.
		return card.color == currentColor
	end
	if card.color == topCard.color then
		return true
	end
	-- Symbol match (drawtwo on drawtwo / reverse on reverse / skip on skip) or number match.
	if card.kind == topCard.kind then
		return true
	end
	if card.kind == "number" and topCard.kind == "number" and card.value == topCard.value then
		return true
	end
	return false
end

-- Wild Draw Four is only *supposed* to be played when you hold no card matching
-- the current color. Bluffing is allowed by official rules (penalty only if challenged).
function Rules.hasColorMatch(hand, color)
	for _, c in ipairs(hand) do
		if c.color == color then
			return true
		end
	end
	return false
end

function Rules.wildDrawFourLegal(hand, currentColor)
	return not Rules.hasColorMatch(hand, currentColor)
end

-- Fisher-Yates
function Rules.shuffle(list, rng)
	for i = #list, 2, -1 do
		local j = rng:NextInteger(1, i)
		list[i], list[j] = list[j], list[i]
	end
	return list
end

function Rules.totalPoints(hand)
	local total = 0
	for _, c in ipairs(hand) do
		total = total + CardDefs.points(c)
	end
	return total
end

return Rules
